4	
5	use comemo::{Track, Tracked, TrackedMut};
6	use ecow::EcoVec;
7	use rayon::iter::{IndexedParallelIterator, IntoParallelIterator, ParallelIterator};
8	use rustc_hash::FxHashSet;
9	use typst_syntax::{FileId, Span};
10	use typst_utils::{LazyHash, Protected};
11	
12	use crate::diag::{HintedStrResult, SourceDiagnostic, SourceResult, StrResult, bail};
13	use crate::foundations::{Styles, Value};
14	use crate::introspection::{Introspect, Introspection, Introspector};
15	use crate::{Library, World};
